vec4 Effect(vec2 uv) {
// Convert UV coordinates to polar form
vec2 p = uv * 2.0 - 1.0;
float r = length(p);
float a = atan(p.y, p.x);
// Create layers with increasing frequency
float d = sin(r * 5.0 + iTime) +
sin(r * 10.0 + iTime * 0.5) +
sin(r * 20.0 + iTime * 0.7);

// Add angular variation
d += sin(a * 6.0 + r * 2.0) * 0.5;

// Mix in noise for complexity
d += fract(sin(r * 10.0 + a * 3.0) * 1234.0) * 0.2;
// Create final pattern by mixing values
float pattern = abs(d) * pow(iTime, 0.5);
// Map to RGB colors for effect
vec3 color = vec3(
sin(pattern * 7.0 + a),
sin(pattern * 5.0 + a * 2.0),
sin(pattern * 3.0 + a * 3.0)
);
return vec4(color, 1.0);
}



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    vec3 col = Effect(uv).rgb;//0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    // Output to screen
    fragColor = vec4(col,1.0);
}
